bool IsEliteRefine(DWORD refineSet)
{
	return refineSet == 501 || refineSet == 530;
}

new:
bool IsEliteRefine(DWORD refineSet)
{
	// MT2009_PLUS_SEONPYEONG_ELITE_V1 (elite sets): Seon-Pyeong's (BLACKSMITH2_MOB) refine sets - a +9 piece dragged onto him becomes the next
	// item (the pl-wiki). 501 / 530 the package's; 39900-39999 the fixed recipes of refine_global.sql (the owner's
	// sheet: weapons 65 -> 80, armours / boots -> 80, weapons 80 -> 87-105, weapons / armours 105 -> cyanite,
	// tools/refineglobal/gen_refineglobal.py ELITE - keep the range in step with it). No other smith, no scroll.
	return refineSet == 501 || refineSet == 530 || (refineSet >= 39900 && refineSet <= 39999);
}

// MT2009_PLUS_SEONPYEONG_FIX_V1 (lua): Seon-Pyeong's talk (quest seon_pyeong) opens the same refine window as a +9
// piece dragged onto him (CHARACTER::ReceiveItem, BLACKSMITH2_MOB), so his "OK" is no dead end.
//   pc.seonpyeong_cells()      the bag cells of the pieces with one of his (elite) recipes, in bag order
//   pc.seonpyeong_refine(cell) the refine window for that piece at the NPC talked to (only Seon-Pyeong, in reach)
ALUA(pc_seonpyeong_cells)
{
	LPCHARACTER ch = CQuestManager::instance().GetCurrentCharacterPtr();
	lua_newtable(L);
	if (!ch)
		return 1;
	int n = 0;
	const int iMax = MIN((int) ch->GetInventoryMaxCount(), (int) INVENTORY_MAX_NUM);
	for (int i = 0; i < iMax; ++i)
	{
		LPITEM item = ch->GetInventoryItem(i);
		if (!item || item->GetCell() != i || item->IsExchanging())
			continue;
		if (!item->GetRefinedVnum() || !IsEliteRefine(item->GetRefineSet()))
			continue;
		lua_pushnumber(L, i);
		lua_rawseti(L, -2, ++n);
	}
	return 1;
}

ALUA(pc_seonpyeong_refine)
{
	CQuestManager& q = CQuestManager::instance();
	LPCHARACTER ch = q.GetCurrentCharacterPtr();
	LPCHARACTER npc = q.GetCurrentNPCCharacterPtr();
	if (!ch || !npc || npc->GetRaceNum() != BLACKSMITH2_MOB || !lua_isnumber(L, 1))
	{
		lua_pushboolean(L, 0);
		return 1;
	}
	const int cell = (int) lua_tonumber(L, 1);
	LPITEM item = (cell >= 0 && cell < (int) ch->GetInventoryMaxCount() && cell < INVENTORY_MAX_NUM) ? ch->GetInventoryItem(cell) : NULL;
	if (!item || item->IsExchanging() || !npc->CanReceiveItem(ch, item)) // his elite recipes only, within 20 m
	{
		lua_pushboolean(L, 0);
		return 1;
	}
	ch->SetRefineNPC(npc);
	lua_pushboolean(L, ch->RefineInformation(cell, REFINE_TYPE_NORMAL) ? 1 : 0);
	return 1;
}

